import threading


class _Flight:
    def __init__(self):
        self.event = threading.Event()
        self.value = None
        self.error = None


class Cache:
    def __init__(self):
        self._values = {}
        self._flights = {}
        self._lock = threading.Lock()

    def get_or_load(self, key, loader):
        with self._lock:
            if key in self._values:
                return self._values[key]
            flight = self._flights.get(key)
            leader = flight is None
            if leader:
                flight = _Flight()
                self._flights[key] = flight

        if not leader:
            flight.event.wait()
            if flight.error is not None:
                raise flight.error
            return flight.value

        try:
            value = loader()
        except Exception as exc:
            with self._lock:
                flight.error = exc
                self._flights.pop(key, None)
                flight.event.set()
            raise

        with self._lock:
            self._values[key] = value
            flight.value = value
            self._flights.pop(key, None)
            flight.event.set()
        return value
